B=devdesk-386-ci-docs-only
mk(){ git checkout -q -b $1 $B && shift && "$@" && git commit -qam "verification only (DEVDESK-386)" && git push -q origin HEAD 2>&1|tail -1; }
c1(){ echo "<!-- ci verification -->" >> docs/backlog.md; }
c2(){ echo "<!-- ci verification -->" >> docs/backlog.md; echo "// ci verification" >> internal/command/parser.go; }
c3(){ echo "<!-- ci verification -->" >> CHANGELOG.md; }
mk tmp-386-docs c1; mk tmp-386-mixed c2; mk tmp-386-changelog c3
git checkout -q $B
for n in docs mixed changelog; do gh -R anthnel/devdesk pr create --base $B --head tmp-386-$n --title "verification only: $n (DEVDESK-386)" --body "Throwaway, will be closed unmerged."; done

